"""The repo's harness: `.ratchet/harness.json`, generated by ratchet and owned by the project.

The kernel never hardcodes how a project is checked. Every check is declared here, wraps
the project's own tools, and reports per-test results ratchet can compare against the base.
"""
from __future__ import annotations

import copy
import fnmatch
from dataclasses import dataclass, field
from pathlib import Path
from typing import Optional

from .util import RatchetError, read_json, write_json

KERNEL = "1"          # harness schema version this kernel understands (see upgrade.py)
VERSION = "1.0.0"     # ratchet release

HARNESS_DIR = ".ratchet"
HARNESS_FILE = ".ratchet/harness.json"

DEFAULT_PROTECT = [".ratchet/**", "t3.json", ".github/workflows/**", "**/__snapshots__/**", "**/*.snap"]

DEFAULTS: dict = {
    "kernel": KERNEL,
    "base": "auto",
    "setup": None,
    "maintenance": None,
    "checks": [],
    "products": [],
    "budgets": [],
    "protect": DEFAULT_PROTECT,
    "tamper_ignore": [],
    "limits": {
        "gate_attempts": 4, "judge_rounds": 2, "worker_attempts": 3, "ci_rounds": 2,
        "parallel_jobs": 4, "machine_slots": 2, "check_timeout_sec": 900, "flaky_reruns": 1,
        "mutants": 8,
    },
    "agents": {
        "max_parallel": 1, "contract_review": True, "judge_panel": 1,
        "coordinator": {"provider": None, "model": None},
        "worker": {"provider": None, "model": None, "options": {}},
        "judge": {"provider": None, "model": None, "options": {}},
    },
    "run": {"pr": "draft"},
}

RESULT_FORMATS = ("auto", "junit", "go-json", "jest-json", "libtest", "result-json", "exit")


@dataclass
class Check:
    name: str
    run: str
    level: str = "fast"               # fast: every change; full: before acceptance
    scope: list = field(default_factory=list)   # changed-path globs that trigger it; [] = any change
    results: str = "auto"
    min_tests: int = 1
    timeout: Optional[int] = None
    cwd: str = "."
    canary: Optional[dict] = None     # {"path": ..., "content": ...}: a test that must fail
    mutate: list = field(default_factory=list)  # source globs mutation probes may touch

    def triggered_by(self, paths: list) -> bool:
        if paths is None:
            return True
        if not self.scope:
            return bool(paths)
        return any(glob_match(p, g) for p in paths for g in self.scope)


_GLOB_CACHE: dict = {}


def _glob_regex(pattern: str):
    rx = _GLOB_CACHE.get(pattern)
    if rx is None:
        import re

        out, i = [], 0
        while i < len(pattern):
            if pattern.startswith("**/", i):
                out.append("(?:.*/)?")
                i += 3
            elif pattern.startswith("**", i):
                out.append(".*")
                i += 2
            elif pattern[i] == "*":
                out.append("[^/]*")
                i += 1
            elif pattern[i] == "?":
                out.append("[^/]")
                i += 1
            else:
                out.append(re.escape(pattern[i]))
                i += 1
        rx = _GLOB_CACHE[pattern] = re.compile("^" + "".join(out) + "$")
    return rx


def glob_match(path: str, pattern: str) -> bool:
    """Path glob: `**/` spans zero or more directories, `*` stays within one; plain fnmatch also accepted."""
    return bool(_glob_regex(pattern).match(path)) or fnmatch.fnmatch(path, pattern)


def _merge(base: dict, over: dict) -> dict:
    out = copy.deepcopy(base)
    for key, val in over.items():
        if isinstance(val, dict) and isinstance(out.get(key), dict):
            out[key] = _merge(out[key], val)
        else:
            out[key] = copy.deepcopy(val)
    return out


def path(root: Path) -> Path:
    return root / HARNESS_FILE


def exists(root: Path) -> bool:
    return path(root).is_file()


def read_raw(root: Path) -> dict:
    raw = read_json(path(root), None)
    if raw is None:
        raise RatchetError(f"no {HARNESS_FILE} here")
    return raw


def load(root: Path) -> dict:
    raw = read_json(path(root), None)
    if raw is None:
        raise RatchetError("this repo has no ratchet harness yet: run `ratchet init` (existing repo) "
                           "or `ratchet new` (fresh repo)")
    if not isinstance(raw, dict):
        raise RatchetError(f"{HARNESS_FILE} must be a JSON object")
    h = _merge(DEFAULTS, {k: v for k, v in raw.items() if not k.startswith("$")})
    if str(h.get("kernel")) != KERNEL:
        h["_needs_upgrade"] = True
    names = [c.get("name") for c in h["checks"]]
    if len(names) != len(set(names)):
        raise RatchetError(f"{HARNESS_FILE}: check names must be unique")
    return h


def save(root: Path, h: dict) -> None:
    data = {k: v for k, v in h.items() if not k.startswith("_")}
    data.setdefault("$schema", "https://github.com/Cosmyk-Labs/ratchet/blob/main/DESIGN.md")
    write_json(path(root), data)


def checks(h: dict, level: str = "fast") -> list[Check]:
    levels = ("fast",) if level == "fast" else ("fast", "full")
    out = []
    for raw in h["checks"]:
        if raw.get("level", "fast") not in levels:
            continue
        if not raw.get("name") or not raw.get("run"):
            raise RatchetError(f"{HARNESS_FILE}: every check needs a name and a run command")
        fmt = raw.get("results", "auto")
        if fmt not in RESULT_FORMATS:
            raise RatchetError(f"check {raw['name']}: results must be one of {', '.join(RESULT_FORMATS)}")
        out.append(Check(
            name=raw["name"], run=raw["run"], level=raw.get("level", "fast"), scope=list(raw.get("scope") or []),
            results=fmt, min_tests=int(raw.get("min_tests", 1)), timeout=raw.get("timeout"),
            cwd=raw.get("cwd", "."), canary=raw.get("canary"), mutate=list(raw.get("mutate") or []),
        ))
    return out


def products_touching(h: dict, paths: list) -> list[dict]:
    out = []
    for prod in h.get("products") or []:
        globs = prod.get("paths") or ["**"]
        if paths is None or any(glob_match(p, g) for p in paths for g in globs):
            out.append(prod)
    return out
